describe('即时锦囊', () => {
  it('无中生有：自己摸 2 张', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [wuzhong('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
    passWuxie(state);
    const a = state.players.find((p) => p.seatId === A)!;
    expect(a.hand).toHaveLength(2);
    expect(state.pending).toEqual({ kind: 'play', seatId: A });
  });

  /**
   * 「目标区域选牌」的验收（用户 2026-09-18 给的规格，docs §5.149）：
   * 三个区域同时可选、明牌精确选、**手牌只能盲选一张牌背**（不泄露牌面）、
   * 逐张判合法性、提交时重新校验。
   */
  describe('目标区域选牌：明牌精确选 / 手牌暗选（拆、顺共用原语）', () => {
    const build = (targetExtra: { equip?: boolean; judgment?: boolean; hand?: number } = {}) => {
      const state = makeGame([
        { seatId: A, name: '甲', heroId: 'vanilla', hand: [guohe('a1'), shunshou('a2')] },
        { seatId: B, name: '乙', heroId: 'vanilla', hand: [] },
        { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
      ]);
      const b = state.players.find((p) => p.seatId === B)!;
      b.equipment.weapon = targetExtra.equip ? wpn('w1') : null;
      if (targetExtra.judgment) b.judgment.push(lebu('j1'));
      b.hand = Array.from({ length: targetExtra.hand ?? 0 }, (_, i) => sha(`b${i + 1}`));
      return { state, b };
    };

    it('三个区域同时可选；明牌给牌名，手牌只给「第 k 张（暗）」——不泄露牌面', () => {
      const { state, b } = build({ equip: true, judgment: true, hand: 2 });
      ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
      passWuxie(state);
      const q = state.pending;
      if (q?.kind !== 'choice') throw new Error(`预期区域选牌，实际是 ${q?.kind}`);
      expect(q.options.map((o) => o.id).sort()).toEqual(
        ['card:j1', 'card:w1', 'hand:0', 'hand:1'].sort(),
      );
      const labels = q.options.map((o) => o.label).join('｜');
      expect(labels).toContain('装备'); // 明牌：牌名
      expect(labels).toContain('判定区');
      expect(labels).toContain('第 1 张手牌（暗');
      // 暗牌的选项里**不能**出现牌名/花色/点数
      expect(labels).not.toContain('杀');
      expect(labels).not.toContain('♠');
      // 选判定区的【乐不思蜀】→ 弃置它
      pickZoneCard(state, A, 'card:j1');
      expect(b.judgment).toHaveLength(0);
      expect(state.discard.some((c) => c.id === 'j1')).toBe(true);
    });

    it('拆：选装备/选暗手牌都正确弃置（手牌是盲选的那一张）', () => {
      const eq = build({ equip: true, hand: 1 });
      ok(act(eq.state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
      passWuxie(eq.state);
      pickZoneCard(eq.state, A, 'card:w1');
      expect(eq.b.equipment.weapon).toBeNull();
      expect(eq.state.discard.some((c) => c.id === 'w1')).toBe(true);

      const hd = build({ hand: 2 });
      ok(act(hd.state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
      passWuxie(hd.state);
      pickZoneCard(hd.state, A, 'hand:0'); // 盲选第 1 张
      expect(hd.b.hand.map((c) => c.id)).toEqual(['b2']);
      expect(hd.state.discard.some((c) => c.id === 'b1')).toBe(true);
    });

    it('顺：选装备/选判定牌都是**实体牌**进使用者手牌（判定牌不结算延时效果）', () => {
      const { state, b } = build({ equip: true, judgment: true });
      const a = state.players.find((p) => p.seatId === A)!;
      state.deck.push(mk('jc', 'sha', 'heart', 1)); // 万一结算了判定，红桃会「无效」——用日志钉死没结算
      ok(act(state, A, { type: 'playCard', cardId: 'a2', targetIds: [B] }));
      passWuxie(state);
      pickZoneCard(state, A, 'card:j1');
      expect(b.judgment).toHaveLength(0);
      expect(a.hand.some((c) => c.id === 'j1')).toBe(true); // 进的是手牌
      // 没有触发它的延时效果：牌直接归甲，流程照常交回出牌阶段（没有插一段判定/生效）
      expect(state.pending).toEqual({ kind: 'play', seatId: A });
    });

    it('提交时重新校验：那张牌已经不在原区域 → 重问一次（不随便换一张）', () => {
      const { state, b } = build({ equip: true, hand: 1 });
      ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
      passWuxie(state);
      const q = state.pending;
      if (q?.kind !== 'choice') throw new Error(`预期区域选牌，实际是 ${q?.kind}`);
      expect(q.options.some((o) => o.id === 'card:w1')).toBe(true);
      // 模拟「跨步期间那张牌被搬走」：直接把武器拿掉
      b.equipment.weapon = null;
      pickZoneCard(state, A, 'card:w1');
      expect(state.log.some((e) => e.message.includes('不在原处'))).toBe(true);
      const again = state.pending;
      if (again?.kind !== 'choice') throw new Error(`预期重问，实际是 ${again?.kind}`);
      expect(again.options.some((o) => o.id === 'card:w1')).toBe(false); // 那张牌已经不在候选里
      pickZoneCard(state, A, 'hand:0'); // 重选一张 → 正常结算
      expect(b.hand).toHaveLength(0);
    });
  });

  it('过河拆桥：弃目标 1 张手牌', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [guohe('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [sha('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
    passWuxie(state);
    pickZoneCard(state, A, 'hand:0'); // 手牌只能盲选一张（规格：不再随机抽）
    const b = state.players.find((p) => p.seatId === B)!;
    expect(b.hand).toHaveLength(0);
    expect(state.discard.some((c) => c.id === 'b1')).toBe(true);
  });

  it('过河拆桥：可拆指定装备', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [guohe('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    const b = state.players.find((p) => p.seatId === B)!;
    b.equipment.weapon = wpn('w1');
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B], targetCardId: 'w1' }));
    passWuxie(state);
    expect(b.equipment.weapon).toBeNull();
    expect(state.discard.some((c) => c.id === 'w1')).toBe(true);
  });

  it('顺手牵羊：获得目标 1 张手牌', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [shunshou('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [sha('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
    passWuxie(state);
    pickZoneCard(state, A, 'hand:0');
    const a = state.players.find((p) => p.seatId === A)!;
    expect(a.hand.some((c) => c.id === 'b1')).toBe(true);
    const b = state.players.find((p) => p.seatId === B)!;
    expect(b.hand).toHaveLength(0);
  });

  it('决斗：交替出杀，不出者受伤', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [juedou('a1'), sha('a2')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [sha('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
    passWuxie(state);
    // B 先出杀
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    // A 出杀
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, A, { type: 'respondCard', cardId: 'a2' }));
    // B 无杀 → 弃权受伤
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, B, { type: 'pass' }));
    const b = state.players.find((p) => p.seatId === B)!;
    expect(b.hp).toBe(3);
  });

  it('火攻：展示同花色 → 弃牌 → 火属性伤害', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [huogong('a1'), mk('a2', 'sha', 'heart')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [shan('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
    passWuxie(state);
    // B 展示手牌（红桃）
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    // A 弃同花色牌
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, A, { type: 'respondCard', cardId: 'a2' }));
    const b = state.players.find((p) => p.seatId === B)!;
    expect(b.hp).toBe(3);
  });

  it('借刀杀人：持有者交出武器', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [jiedao('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    const b = state.players.find((p) => p.seatId === B)!;
    b.equipment.weapon = wpn('w1');
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B, C] }));
    passWuxie(state);
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, B, { type: 'pass' }));
    const a = state.players.find((p) => p.seatId === A)!;
    expect(a.hand.some((c) => c.id === 'w1')).toBe(true);
    expect(b.equipment.weapon).toBeNull();
  });

  it('南蛮入侵：依次出杀或受伤', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [nanman('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [sha('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
    passWuxie(state);
    // B 出杀
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    // C 弃权 → 受伤
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, C, { type: 'pass' }));
    const c = state.players.find((p) => p.seatId === C)!;
    expect(c.hp).toBe(3);
    expect(state.pending).toEqual({ kind: 'play', seatId: A });
  });

  it('万箭齐发：依次出闪或受伤', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [wanjian('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [shan('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
    passWuxie(state);
    // B 出闪
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    // C 弃权 → 受伤
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, C, { type: 'pass' }));
    const c = state.players.find((p) => p.seatId === C)!;
    expect(c.hp).toBe(3);
  });

  it('桃园结义：所有存活回 1 体力', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [taoyuan('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [], hp: 3 },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [], hp: 2 },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
    passWuxie(state);
    const a = state.players.find((p) => p.seatId === A)!;
    const b = state.players.find((p) => p.seatId === B)!;
    const c = state.players.find((p) => p.seatId === C)!;
    expect(a.hp).toBe(4); // 满血不回
    expect(b.hp).toBe(4);
    expect(c.hp).toBe(3);
  });

  it('无懈可击：取消锦囊效果', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [wuzhong('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [wuxie('b1')] },
      // 丙也留一张无懈：这样打出一张之后**抵消轮**才存在
      // （新规则：身上没有无懈的人根本不会被问，见 openWuxieWindow 的说明）
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [wuxie('c1')] },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
    expect(state.pending?.kind).toBe('wuxieQueue');
    if (state.pending?.kind === 'wuxieQueue') expect(state.pending.askQueue).toEqual([B, C]);
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    // 打出一张无懈之后**不直接结算**：还要给持有无懈的人一次「再抵消这一张」的机会
    expect(state.pending?.kind).toBe('wuxieQueue');
    passWuxie(state);
    const a = state.players.find((p) => p.seatId === A)!;
    expect(a.hand).toHaveLength(0); // 没有摸牌（锦囊被取消）
    expect(state.pending).toEqual({ kind: 'play', seatId: A });
  });

  it('无懈可击不能主动使用', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [wuxie('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [] },
    ]);
    fail(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
  });

  it('南蛮入侵：濒死救援后继续推进', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [nanman('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [sha('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [tao('c1')], hp: 1 },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
    passWuxie(state);
    // B 出杀
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    // C 弃权 → 受 1 伤害 → hp=0 → 濒死
    ok(act(state, C, { type: 'pass' }));
    expect(state.pending?.kind).toBe('respondDeath');
    // C 用桃自救
    ok(act(state, C, { type: 'respondCard', cardId: 'c1' }));
    const c = state.players.find((p) => p.seatId === C)!;
    expect(c.hp).toBe(1);
    expect(c.alive).toBe(true);
    // 回到 A 的出牌阶段
    expect(state.pending).toEqual({ kind: 'play', seatId: A });
  });

  it('南蛮入侵：无人救援 → 阵亡后继续', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [nanman('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [sha('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [], hp: 1 },
    ]);
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [] }));
    passWuxie(state);
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    ok(act(state, C, { type: 'pass' }));
    // C 濒死 → 无人有桃 → 阵亡
    passDeathSaves(state);
    const c = state.players.find((p) => p.seatId === C)!;
    expect(c.alive).toBe(false);
    expect(state.pending).toEqual({ kind: 'play', seatId: A });
  });

  it('借刀杀人：持有者出杀 → 正常结算', () => {
    const state = makeGame([
      { seatId: A, name: '甲', heroId: 'vanilla', hand: [jiedao('a1')] },
      { seatId: B, name: '乙', heroId: 'vanilla', hand: [sha('b1')] },
      { seatId: C, name: '丙', heroId: 'vanilla', hand: [shan('c1')] },
    ]);
    const b = state.players.find((p) => p.seatId === B)!;
    b.equipment.weapon = wpn('w1');
    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B, C] }));
    passWuxie(state);
    // B 对 C 出杀
    expect(state.pending?.kind).toBe('respondTrick');
    ok(act(state, B, { type: 'respondCard', cardId: 'b1' }));
    // C 出闪
    expect(state.pending?.kind).toBe('respondSha');
    ok(act(state, C, { type: 'respondCard', cardId: 'c1' }));
    // 回到 A 的出牌阶段
    expect(state.pending).toEqual({ kind: 'play', seatId: A });
    const c = state.players.find((p) => p.seatId === C)!;
    expect(c.hp).toBe(4); // 未受伤
  });
});

