    ok(act(state, A, { type: 'playCard', cardId: 'a1', targetIds: [B] }));
    expect(state.pending!.kind).toBe('respondSha');
    ok(act(state, B, { type: 'pass' }));
    expect(b.hp).toBe(b.maxHp - 1);
